package me.eiakoji.eip.transformation;

import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Production Claim Check Pattern Implementation with SHA-256 Integrity Verification.
 */
public final class ClaimCheckManager {

    public record ClaimCheckToken(
        UUID messageId,
        URI storageUri,
        String sha256Digest,
        long sizeBytes,
        Instant createdAt,
        Duration ttl
    ) {}

    public interface BlobStore {
        URI put(byte[] data, String contentType);
        byte[] get(URI uri);
        void delete(URI uri);
    }

    public static final class InMemoryBlobStore implements BlobStore {
        private final Map<URI, byte[]> store = new ConcurrentHashMap<>();

        @Override
        public URI put(byte[] data, String contentType) {
            URI uri = URI.create("blob://storage.eiakoji.me/" + UUID.randomUUID());
            store.put(uri, data.clone());
            return uri;
        }

        @Override
        public byte[] get(URI uri) {
            byte[] data = store.get(uri);
            if (data == null) {
                throw new NoSuchElementException("Blob not found at URI: " + uri);
            }
            return data.clone();
        }

        @Override
        public void delete(URI uri) {
            store.remove(uri);
        }
    }

    private final BlobStore blobStore;

    public ClaimCheckManager(BlobStore blobStore) {
        this.blobStore = Objects.requireNonNull(blobStore);
    }

    public ClaimCheckToken checkIn(UUID messageId, byte[] payload, String contentType, Duration ttl) {
        String digest = computeSha256(payload);
        URI uri = blobStore.put(payload, contentType);

        return new ClaimCheckToken(
            messageId,
            uri,
            digest,
            payload.length,
            Instant.now(),
            ttl
        );
    }

    public byte[] checkOut(ClaimCheckToken token) {
        byte[] payload = blobStore.get(token.storageUri());
        String actualDigest = computeSha256(payload);

        if (!actualDigest.equalsIgnoreCase(token.sha256Digest())) {
            throw new IllegalStateException("Claim Check integrity violation! Expected: " 
                + token.sha256Digest() + " but computed: " + actualDigest);
        }

        return payload;
    }

    public void release(ClaimCheckToken token) {
        blobStore.delete(token.storageUri());
    }

    private static String computeSha256(byte[] data) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(data);
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm missing from JVM", e);
        }
    }
}
